 record Invitation(UUID id,long revision,String purpose,String recipientEmail,UUID targetOrganizationId,String state,String deliveryState,String expiresAt,String createdAt,String updatedAt){}
 static Invitation invitations(ResultSet r)throws SQLException{return new Invitation(r.getObject("id",UUID.class),r.getLong("revision"),r.getString("purpose"),r.getString("recipientEmail"),r.getObject("targetOrganizationId",UUID.class),r.getString("state"),r.getString("deliveryState"),time(r.getTimestamp("expiresAt")),time(r.getTimestamp("createdAt")),time(r.getTimestamp("updatedAt")));}
