 static Product products(ResultSet r)throws SQLException{return new Product(r.getObject("id",UUID.class),r.getLong("revision"),r.getString("sku"),r.getString("name"),r.getString("description"),r.getObject("unitId",UUID.class),r.getString("packDescription"),r.getObject("categoryId",UUID.class),uuids(r,"tagIds"),uuids(r,"galleryAssetIds"),r.getLong("minimumQuantity"),r.getLong("quantityStep"),r.getBoolean("featured"),r.getBoolean("unitAndPackFrozen"),r.getString("state"),time(r.getTimestamp("createdAt")),time(r.getTimestamp("updatedAt")));}
 record SkuReservation(UUID productId,String normalizedSku,boolean retired){}
 static SkuReservation sku_reservations(ResultSet r)throws SQLException{return new SkuReservation(r.getObject("productId",UUID.class),r.getString("normalizedSku"),r.getBoolean("retired"));}
 record Taxonomy(UUID id,long revision,String kind,String name,boolean nameFrozen,boolean deleted,String createdAt,String updatedAt){}
 static Taxonomy taxonomy(ResultSet r)throws SQLException{return new Taxonomy(r.getObject("id",UUID.class),r.getLong("revision"),r.getString("kind"),r.getString("name"),r.getBoolean("nameFrozen"),r.getBoolean("deleted"),time(r.getTimestamp("createdAt")),time(r.getTimestamp("updatedAt")));}
 record AgreedPrice(UUID id,UUID buyerId,UUID productId,long revision,String unitPrice,boolean removed,boolean confirmationRequired,String createdAt){}
