 record Inventory(UUID productId,long revision,Integer availableCount,boolean trackingEnabled,boolean confirmationRequired,long creditQuantity,long maximumSettableCount){}
 static Inventory inventory(ResultSet r)throws SQLException{return new Inventory(r.getObject("productId",UUID.class),r.getLong("revision"),(Integer)r.getObject("availableCount"),r.getBoolean("trackingEnabled"),r.getBoolean("confirmationRequired"),r.getLong("creditQuantity"),r.getLong("maximumSettableCount"));}
 record StockHistory(UUID id,UUID productId,String type,Integer beforeCount,long afterCount,long delta,String reason,UUID actorId,UUID orderId,String createdAt){}
 static StockHistory stock_history(ResultSet r)throws SQLException{return new StockHistory(r.getObject("id",UUID.class),r.getObject("productId",UUID.class),r.getString("type"),(Integer)r.getObject("beforeCount"),r.getLong("afterCount"),r.getLong("delta"),r.getString("reason"),r.getObject("actorId",UUID.class),r.getObject("orderId",UUID.class),time(r.getTimestamp("createdAt")));}
